  "implementation": "def solve(case):
    matrix = case['matrix']
    idf = case['idf']
    vector = case['vector']
    m = len(matrix)
    n = len(matrix[0])
    W = [[matrix[i][j] * idf[j] for j in range(n)] for i in range(m)]
    WTW = [[0.0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            s = 0.0
            for k in range(m):
                s += W[k][i] * W[k][j]
            WTW[i][j] = s
    WTy = [0.0]*n
    for i in range(n):
        s = 0.0
        for k in range(m):
            s += W[k][i] * vector[k]
        WTy[i] = s
    A = [WTW[i][:] + [WTy[i]] for i in range(n)]
    for col in range(n):
        max_row = max(range(col, n), key=lambda r: abs(A[r][col]))
        if A[max_row][col] == 0:
            x = [0.0]*n
            break
        A[col], A[max_row] = A[max_row], A[col]
        pivot = A[col][col]
        A[col] = [val / pivot for val in A[col]]
        for row in range(n):
            if row != col:
                factor = A[row][col]
                if factor != 0:
                    A[row] = [A[row][i] - factor * A[col][i] for i in range(n+1)]
    else:
        x = [A[i][n] for i in range(n)]
    result = [sum(W[i][j] * x[j] for j in range(n)) for i in range(m)]
    return {'degree': x, 'result': result}"
}
